import{_ as t,o as a,c as o,an as l}from"./chunks/framework.DAsE5xAf.js";const y=JSON.parse('{"title":"Linear Algebra","description":"","frontmatter":{},"headers":[],"relativePath":"linalg.md","filePath":"linalg.md","lastUpdated":null}'),d={name:"linalg.md"};function n(i,e,r,c,s,h){return a(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="Linear-Algebra" tabindex="-1">Linear Algebra <a class="header-anchor" href="#Linear-Algebra" aria-label="Permalink to &quot;Linear Algebra {#Linear-Algebra}&quot;">​</a></h1><p>cuNumeric.jl provides matrix multiplication, solves, Cholesky, eigen, SVD, QR, and related helpers for <code>NDArray</code>. For Einstein-index contractions, see <a href="./api_tensor">Tensor Contractions</a>.</p><h2 id="Supported-element-types" tabindex="-1">Supported element types <a class="header-anchor" href="#Supported-element-types" aria-label="Permalink to &quot;Supported element types {#Supported-element-types}&quot;">​</a></h2><p>All of the decompositions accept <code>Float32</code>, <code>Float64</code>, <code>ComplexF32</code>, and <code>ComplexF64</code>. Integer and <code>Bool</code> inputs are converted to <code>Float64</code>. As everywhere else in the package, that conversion needs <code>@allowpromotion</code> (or <code>allowpromotion</code>) only when it widens the element type, so <code>Int64</code> and <code>UInt64</code> pass through silently while <code>Int32</code>, smaller integers, and <code>Bool</code> do not.</p><h2 id="In-this-section" tabindex="-1">In this section <a class="header-anchor" href="#In-this-section" aria-label="Permalink to &quot;In this section {#In-this-section}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Page</th><th style="text-align:left;">Topics</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="./linalg/operations">Standard functions</a></td><td style="text-align:left;">Matrix and vector products, norms, linear systems, and helpers</td></tr><tr><td style="text-align:left;"><a href="./linalg/factorizations">Factorizations</a></td><td style="text-align:left;">Cholesky, eigendecomposition, SVD, and QR</td></tr><tr><td style="text-align:left;"><a href="./linalg/batched">Batched operations</a></td><td style="text-align:left;">Solves and decompositions for stacks of matrices</td></tr><tr><td style="text-align:left;"><a href="./linalg/diagonal">Diagonal and identity</a></td><td style="text-align:left;">Structured diagonal matrices and uniform scaling</td></tr><tr><td style="text-align:left;"><a href="./linalg/tuning">Tuning</a></td><td style="text-align:left;">Multi-GPU selection rules, cutoffs, and block sizes</td></tr></tbody></table><h2 id="Which-entry-point-to-use" tabindex="-1">Which entry point to use <a class="header-anchor" href="#Which-entry-point-to-use" aria-label="Permalink to &quot;Which entry point to use {#Which-entry-point-to-use}&quot;">​</a></h2><p>Single matrices use familiar <code>LinearAlgebra</code> functions. Most decompositions return standard factorization objects; QR returns cuNumeric&#39;s <code>NDArrayQR</code>. Stacks of matrices have no <code>LinearAlgebra</code> equivalent, so they get their own <code>batched_*</code> names.</p><table tabindex="0"><thead><tr><th style="text-align:left;">Single matrix (2D)</th><th style="text-align:left;">Returns</th><th style="text-align:left;">Stack of matrices (3D)</th></tr></thead><tbody><tr><td style="text-align:left;"><code>LinearAlgebra.cholesky(A)</code></td><td style="text-align:left;"><code>Cholesky</code></td><td style="text-align:left;"><code>cuNumeric.batched_cholesky(A)</code></td></tr><tr><td style="text-align:left;"><code>LinearAlgebra.eigen(A)</code></td><td style="text-align:left;"><code>Eigen</code></td><td style="text-align:left;"><code>cuNumeric.batched_eigen(A)</code></td></tr><tr><td style="text-align:left;"><code>LinearAlgebra.eigvals(A)</code></td><td style="text-align:left;"><code>NDArray</code></td><td style="text-align:left;"><code>cuNumeric.batched_eigvals(A)</code></td></tr><tr><td style="text-align:left;"><code>LinearAlgebra.svd(A)</code></td><td style="text-align:left;"><code>SVD</code></td><td style="text-align:left;">not supported</td></tr><tr><td style="text-align:left;"><code>LinearAlgebra.qr(A)</code></td><td style="text-align:left;"><code>NDArrayQR</code></td><td style="text-align:left;">not supported</td></tr><tr><td style="text-align:left;"><code>cuNumeric.solve(A, b)</code>, <code>A \\ b</code></td><td style="text-align:left;"><code>NDArray</code></td><td style="text-align:left;"><code>cuNumeric.batched_solve(A, B)</code></td></tr></tbody></table><h2 id="Not-available-yet" tabindex="-1">Not available yet <a class="header-anchor" href="#Not-available-yet" aria-label="Permalink to &quot;Not available yet {#Not-available-yet}&quot;">​</a></h2><p>There is no public dense-matrix <code>lu</code>, matrix <code>inv</code>, or <code>ldiv!</code> yet (beyond the <a href="./linalg/diagonal">diagonal-matrix operations</a>). Elementwise <code>inv</code> / <code>^-1</code> are unary operations, not matrix inverse.</p><p>Also missing: <code>eigh</code> / Hermitian eigen (needs <code>Hermitian</code> and <code>Symmetric</code> support on <code>NDArray</code>), and batched SVD and QR.</p>',12)])])}const p=t(d,[["render",n]]);export{y as __pageData,p as default};
